#!/usr/bin/env python3
"""TAVIZ rebrand installer (site). Run from the project folder:  python3 install_taviz_site.py .
Renames the visible brand TAVIX -> TAVIZ (ONE TAVIZ AI / TAVIZ AI) and installs the new logo layers.
Domains, emails, env vars and the registered legal name TavixAI Technologies Solution Private Limited are NOT changed.
Old files are copied to _backup_before_taviz first."""
import re,os,sys,shutil,base64
ROOT=os.path.abspath(sys.argv[1] if len(sys.argv)>1 else '.')
KIND='site'
MARK={'one':'backend/app/main.py','site':'backend/main.py'}[KIND]
if not os.path.exists(os.path.join(ROOT,MARK)) or not os.path.isdir(os.path.join(ROOT,'frontend','src')):
    sys.exit('This is not the %s folder (cannot find %s). Open the right folder and try again.'%({'one':'ONE TAVIX AI (tavix-ai 5)','site':'TAVIX company website (TAVIX 9)'}[KIND],MARK))
if KIND=='one' and os.path.exists(os.path.join(ROOT,'backend','company_kb')): sys.exit('This looks like the company website folder. Use the other installer.')
BIN={'logo.png': '', 'logo-full.png': '', 'logo-wl.png': '', 'logo-wr.png': '', 'logo-t.png': '', 'logo-t-l.png': '', 'logo-a.png': '', 'logo-a-l.png': '', 'logo-v.png': '', 'logo-v-l.png': '', 'logo-i.png': '', 'logo-i-l.png': '', 'logo-z.png': '', 'logo-z-l.png': ''}
PAT=re.compile(r'(?<![A-Za-z0-9_\-./@~])(TAVIX|Tavix)(?![A-Za-z0-9_\-@])(?!\.in)(?!\.com)')
sub=lambda m:'TAVIZ' if m.group(1)=='TAVIX' else 'Taviz'
EXT={'.jsx','.js','.css','.html','.py','.md','.json','.txt'}
SKIP={'node_modules','dist','.git','ml','__pycache__','deploy'}
BK=os.path.join(ROOT,'_backup_before_taviz')
def backup(p):
    rel=os.path.relpath(p,ROOT); d=os.path.join(BK,rel)
    if not os.path.exists(d) and os.path.exists(p):
        os.makedirs(os.path.dirname(d),exist_ok=True); shutil.copy2(p,d)
changed=0; files=0
for sd in ['frontend/src','frontend/index.html','frontend/test','backend','README.md','docs']:
    p=os.path.join(ROOT,sd)
    fl=[p] if os.path.isfile(p) else [os.path.join(dp,f) for dp,dn,fn in os.walk(p) for f in fn]
    for f in fl:
        parts=set(os.path.relpath(f,ROOT).split(os.sep))
        if parts&SKIP or any(x.startswith('_backup') for x in parts): continue
        if os.path.splitext(f)[1] not in EXT or f.endswith('package-lock.json'): continue
        try: t=open(f,encoding='utf-8').read()
        except Exception: continue
        n,c=PAT.subn(sub,t)
        if c: backup(f); open(f,'w',encoding='utf-8').write(n); changed+=c; files+=1
def edit(rel,old,new):
    p=os.path.join(ROOT,rel)
    if not os.path.exists(p): return
    t=open(p,encoding='utf-8').read()
    if old in t: backup(p); open(p,'w',encoding='utf-8').write(t.replace(old,new))
edit('frontend/src/components/LogoAnim.jsx','["t", "a", "v", "i", "x"]','["t", "a", "v", "i", "z"]')
edit('frontend/src/components/LogoAnim.jsx','(k === "x" ? " lg-x" : "")','(k === "z" ? " lg-x" : "")')
edit('frontend/src/components/DataRain.jsx','01TAVIX','01TAVIZ')
edit('frontend/src/pages/Landing.jsx','> one tavix ai<','> one taviz ai<')
edit('backend/app/routers/portfolio.py','"api", "tavix",','"api", "tavix", "taviz",')
kb=os.path.join(ROOT,'backend/company_kb/01_company.md')
if os.path.exists(kb):
    t=open(kb,encoding='utf-8').read()
    if 'Name change' not in t:
        backup(kb); open(kb,'w',encoding='utf-8').write(t.replace('## Who founded TAVIZ','## Name change\nTAVIZ AI was earlier written as TAVIX AI, and ONE TAVIZ AI as ONE TAVIX AI. It is the same company, with a new name and logo. The website addresses and email addresses stay the same for now.\n## Who founded TAVIZ',1))
pub=os.path.join(ROOT,'frontend','public'); os.makedirs(pub,exist_ok=True)
for name,b in BIN.items():
    p=os.path.join(pub,name); backup(p); open(p,'wb').write(base64.b64decode(b))
for old in ('logo-x.png','logo-x-l.png'):
    p=os.path.join(pub,old)
    if os.path.exists(p): backup(p); os.remove(p)
# checks
bad=[]
la=open(os.path.join(ROOT,'frontend/src/components/LogoAnim.jsx'),encoding='utf-8').read()
if '"z"]' not in la: bad.append('LogoAnim letters not updated')
for n in ('logo-z.png','logo-z-l.png','logo-full.png'):
    if not os.path.exists(os.path.join(pub,n)): bad.append('missing '+n)
print('Renamed %d places in %d files; installed %d logo files.'%(changed,files,len(BIN)))
if bad: sys.exit('PROBLEM: '+'; '.join(bad))
print('Done. Old copies are in _backup_before_taviz.')
